"""Metrics collection for monitoring ingestion pipelines."""

import time
import functools
from typing import Any, Callable

_registry: dict[str, Any] = {}


class Counter:
    def __init__(self, name: str, description: str = "") -> None:
        self.name = name
        self.description = description
        self._value: int = 0

    def inc(self, amount: int = 1) -> None:
        self._value += amount

    def value(self) -> int:
        return self._value

    def reset(self) -> None:
        self._value = 0

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "type": "counter", "value": self._value}


class Gauge:
    def __init__(self, name: str, description: str = "") -> None:
        self.name = name
        self.description = description
        self._value: float = 0

    def set(self, value: float) -> None:
        self._value = value

    def inc(self, amount: int = 1) -> None:
        self._value += amount

    def dec(self, amount: int = 1) -> None:
        self._value -= amount

    def value(self) -> float:
        return self._value

    def to_dict(self) -> dict[str, Any]:
        return {"name": self.name, "type": "gauge", "value": self._value}


class Histogram:
    def __init__(self, name: str, description: str = "", buckets: list[float] | None = None) -> None:
        self.name = name
        self.description = description
        self.buckets = buckets or [0.01, 0.05, 0.1, 0.25, 0.5, 1.0, 5.0, 10.0]
        self._observations: list[float] = []

    def observe(self, value: float) -> None:
        self._observations.append(value)

    def count(self) -> int:
        return len(self._observations)

    def sum(self) -> float:
        return sum(self._observations) if self._observations else 0

    def avg(self) -> float:
        if not self._observations:
            return 0.0
        return self.sum() / self.count()

    def percentile(self, p: float) -> float:
        if not self._observations:
            return 0.0
        sorted_obs = sorted(self._observations)
        idx = int(len(sorted_obs) * p / 100)
        return sorted_obs[min(idx, len(sorted_obs) - 1)]

    def bucket_counts(self) -> dict[float, int]:
        counts: dict[float, int] = {}
        for boundary in self.buckets:
            counts[boundary] = sum(1 for v in self._observations if v <= boundary)
        counts[float("inf")] = len(self._observations)
        return counts

    def to_dict(self) -> dict[str, Any]:
        return {
            "name": self.name,
            "type": "histogram",
            "count": self.count(),
            "sum": self.sum(),
            "avg": round(self.avg(), 6),
            "p50": self.percentile(50),
            "p95": self.percentile(95),
            "p99": self.percentile(99),
        }


_counter_registry: dict[str, Counter] = {}
_gauge_registry: dict[str, Gauge] = {}
_histogram_registry: dict[str, Histogram] = {}


def counter(name: str, description: str = "") -> Counter:
    """Get or create a counter metric."""
    if name not in _counter_registry:
        _counter_registry[name] = Counter(name, description)
    return _counter_registry[name]


def gauge(name: str, description: str = "") -> Gauge:
    """Get or create a gauge metric."""
    if name not in _gauge_registry:
        _gauge_registry[name] = Gauge(name, description)
    return _gauge_registry[name]


def histogram(name: str, description: str = "", buckets: list[float] | None = None) -> Histogram:
    """Get or create a histogram metric."""
    if name not in _histogram_registry:
        _histogram_registry[name] = Histogram(name, description, buckets)
    return _histogram_registry[name]


def report() -> dict[str, dict[str, Any]]:
    """Generate a report of all registered metrics."""
    return {name: metric.to_dict() for name, metric in sorted(_counter_registry.items())}


def reset_all() -> None:
    """Reset all metrics."""
    _counter_registry.clear()
    _gauge_registry.clear()
    _histogram_registry.clear()


def timed(metric_name: str) -> Callable[..., Any]:
    """Decorator that records function execution time to a histogram."""
    def decorator(fn: Callable[..., Any]) -> Callable[..., Any]:
        hist = histogram(metric_name)

        @functools.wraps(fn)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            start = time.time()
            result = fn(*args, **kwargs)
            elapsed = time.time() - start
            hist.observe(elapsed)
            return result
        return wrapper
    return decorator


def counted(metric_name: str) -> Callable[..., Any]:
    """Decorator that increments a counter each time the function is called."""
    def decorator(fn: Callable[..., Any]) -> Callable[..., Any]:
        ctr = counter(metric_name)

        @functools.wraps(fn)
        def wrapper(*args: Any, **kwargs: Any) -> Any:
            ctr.inc()
            return fn(*args, **kwargs)
        return wrapper
    return decorator
