from .models import Record, BatchResult

logger = logging.getLogger(__name__)


class BaseWriter:
    def __init__(self, output_path: str, buffer_size: int = 100) -> None:
        self.output_path: str = output_path
        self.buffer_size: int = buffer_size
        self._buffer: list[Any] = []
        self._total_written: int = 0

    def write_record(self, record: Any) -> None:
        self._buffer.append(record)
        if len(self._buffer) >= self.buffer_size:
            self.flush()

    def write_batch(self, records: list[Any]) -> None:
        for record in records:
            self.write_record(record)

    def flush(self) -> None:
        raise NotImplementedError

    def close(self) -> None:
        if self._buffer:
            self.flush()

    @property
    def total_written(self) -> int:
        return self._total_written

    def __enter__(self) -> "BaseWriter":
        return self

    def __exit__(self, exc_type: type[BaseException] | None, exc_val: BaseException | None, exc_tb: Any) -> Literal[False]:
        self.close()
        return False


class JsonWriter(BaseWriter):
    def __init__(self, output_path: str, buffer_size: int = 100, pretty: bool = False) -> None:
        super().__init__(output_path, buffer_size)
        self.pretty: bool = pretty
        self._first_write: bool = True
        # Initialize the file with an opening bracket
        with open(self.output_path, "w") as f:
            f.write("[\n")

    def flush(self) -> None:
        if not self._buffer:
            return

        with open(self.output_path, "a") as f:
            for record in self._buffer:
                data = record.to_dict() if isinstance(record, Record) else record
                if not self._first_write:
                    f.write(",\n")
                if self.pretty:
                    f.write(json.dumps(data, indent=2, default=str))
                else:
                    f.write(json.dumps(data, default=str))
                self._first_write = False

        self._total_written += len(self._buffer)
        self._buffer.clear()
        logger.debug(f"Flushed {len(self._buffer)} records to {self.output_path}")

    def close(self) -> None:
        super().close()
        # Close the JSON array
        with open(self.output_path, "a") as f:
            f.write("\n]")


class CsvWriter(BaseWriter):
    def __init__(self, output_path: str, buffer_size: int = 100, fieldnames: list[str] | None = None) -> None:
        super().__init__(output_path, buffer_size)
        self.fieldnames: list[str] | None = fieldnames
        self._header_written: bool = False

    def flush(self) -> None:
        if not self._buffer:
            return

        rows: list[dict[str, Any]] = []
        for record in self._buffer:
            data = record.to_dict() if isinstance(record, Record) else record
            rows.append(data)

        if not self._header_written and self.fieldnames is None:
            self.fieldnames = list(rows[0].keys())

        mode: str = "a" if self._header_written else "w"
        with open(self.output_path, mode, newline="") as f:
            writer = csv.DictWriter(f, fieldnames=self.fieldnames, extrasaction="ignore")
            if not self._header_written:
                writer.writeheader()
                self._header_written = True
            writer.writerows(rows)

        self._total_written += len(self._buffer)
        self._buffer.clear()


class NullWriter(BaseWriter):
    """Discards all records. Useful for dry-run or testing."""

    def flush(self) -> None:
        self._total_written += len(self._buffer)
        self._buffer.clear()


def create_writer(format: str, output_path: str, **kwargs: Any) -> BaseWriter:
    """Factory function to create the appropriate writer."""
    writers: dict[str, type[BaseWriter]] = {
        "json": JsonWriter,
        "csv": CsvWriter,
        "null": NullWriter,
    }
    cls = writers.get(format)
    if cls is None:
        raise ValueError(f"Unknown writer format: {format}. Available: {list(writers.keys())}")
    return cls(output_path, **kwargs)


def write_records(records: list[Any], output_path: str, format: str = "json", **kwargs: Any) -> BatchResult:
    """Convenience function to write a list of records to a file."""
    result = BatchResult()
    start = time.time()
    try:
        writer = create_writer(format, output_path, **kwargs)
        for record in records:
            writer.write_record(record)
        writer.close()
        result.success = len(records)
        result.total = len(records)
    except Exception as e:
        result.failed = len(records)
        result.errors.append(str(e))
    finally:
        result.duration_ms = (time.time() - start) * 1000
    return result


def write_records_batched(records: Iterator[Any], output_path: str, format: str = "json", batch_size: int = 1000, **kwargs: Any) -> BatchResult:
    """Write records in batches to a file."""
    result = BatchResult()
    batch: list[Any] = []
    start = time.time()
    try:
        writer = create_writer(format, output_path, **kwargs)
        for record in records:
            batch.append(record)
            if len(batch) >= batch_size:
                for r in batch:
                    writer.write_record(r)
                writer.flush()
                batch = []
        if batch:
            for r in batch:
                writer.write_record(r)
            writer.flush()
        writer.close()
        result.success = sum(1 for _ in records)
        result.total = sum(1 for _ in records)
    except Exception as e:
        result.failed = sum(1 for _ in records)
        result.errors.append(str(e))
    finally:
        result.duration_ms = (time.time() - start) * 1000
    return result


def write_records_file(records: list[Any], output_path: str, format: str = "json", **kwargs: Any) -> None:
    """Write records to a file and return the result."""
    write_records(records, output_path, format, **kwargs)


def write_records_stream(records: Iterator[Any], output_path: str, format: str = "json", **kwargs: Any) -> None:
    """Write records from a stream to a file."""
    for record in records:
        write_record(record, output_path, format, **kwargs)


def write_record(record: Any, output_path: str, format: str = "json", **kwargs: Any) -> None:
    """Write a single record to a file."""
    result = write_records([record], output_path, format, **kwargs)
    if result.failed > 0:
        raise ValueError(f"Failed to write record: {result.errors}")


def write_records_batch(records: list[Any], output_path: str, format: str = "json", **kwargs: Any) -> BatchResult:
    """Write a batch of records to a file."""
    return write_records(records, output_path, format, **kwargs)
